package com.dy.artisan3d.domain.modeldata class ProductDetails(    val id: Int,    val slug: String,    val name: String,    val description: String,    val category: CategoryDetails,    val brand: BrandDetails,    val status: Status,    val details: ProductDetail,    val images: ProductImages,    val createdAt: String,    val updatedAt: String)data class CategoryDetails(    val id: Int,    val slug: String,    val name: String)data class BrandDetails(    val id: Int,    val name: String,    val address: String,    val image: String?)data class Status(    val id: Int,    val name: String)data class ProductDetail(    val id: Int,    val colors: List<Color>,    val materials: List<Material>,    val tags: List<Tag>,    val madeDate: String,    val size: String?)data class Color(    val id: Int,    val name: String,    val code: String)data class Material(    val id: Int,    val name: String,    val slug: String)data class Tag(    val id: Int,    val name: String,    val slug: String)data class ProductImages(    val main: String,    val glb: String,    val extra: List<String>)// Helper extension - Description-ni parse qilish uchundata class DescriptionField(    val label: String,    val value: String)fun String.parseDescription(): List<DescriptionField> {    return this.split("\n")        .mapNotNull { line ->            val parts = line.split(":", limit = 2)            if (parts.size == 2) {                DescriptionField(                    label = parts[0].trim(),                    value = parts[1].trim()                )            } else null        }}